package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden represents a kindergarten garden.
type Garden struct {
	rows     [2]string
	positions map[string]int // child -> index (position in sorted order)
}

var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, errors.New("diagram must start with a newline")
	}
	rows := strings.Split(strings.TrimPrefix(diagram, "\n"), "\n")
	if len(rows) != 2 {
		return nil, errors.New("diagram must have exactly two rows")
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[0])%2 != 0 {
		return nil, errors.New("diagram must have an even number of cups")
	}
	for _, r := range rows {
		for i := 0; i < len(r); i++ {
			if _, ok := plantNames[r[i]]; !ok {
				return nil, fmt.Errorf("invalid cup code %q", r[i])
			}
		}
	}
	// Check for duplicates
	seen := make(map[string]bool, len(children))
	for _, c := range children {
		if seen[c] {
			return nil, fmt.Errorf("duplicate child name %q", c)
		}
		seen[c] = true
	}
	if 2*len(children) > len(rows[0]) {
		return nil, errors.New("too many children for the number of cups")
	}
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	positions := make(map[string]int, len(sorted))
	for i, c := range sorted {
		positions[c] = i
	}
	return &Garden{rows: [2]string{rows[0], rows[1]}, positions: positions}, nil
}

func (g *Garden) Plants(child string) ([]string, bool) {
	i, ok := g.positions[child]
	if !ok {
		return nil, false
	}
	off := 2 * i
	return []string{
		plantNames[g.rows[0][off]],
		plantNames[g.rows[0][off+1]],
		plantNames[g.rows[1][off]],
		plantNames[g.rows[1][off+1]],
	}, true
}
