package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden represents a kindergarten garden: two rows of cups and the
// assignment of those cups to the children in the class.
type Garden struct {
	rows    [2]string
	indices map[string]int // child -> position in alphabetically sorted order
}

// plantNames maps the single-letter diagram codes to plant names.
var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// NewGarden parses the diagram and the list of children.
//
// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//	diagram := `
//	VVCCGG
//	VVCCGG`
//
// The diagram must consist of exactly two rows of equal length, with an
// even number of cups per row, and every cup must be a valid plant code.
// The children must have unique names.  The children are assigned cups
// in alphabetical order; the argument slice is not modified.
func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, errors.New("diagram must start each row with a newline")
	}
	rows := strings.Split(strings.TrimPrefix(diagram, "\n"), "\n")
	if len(rows) != 2 {
		return nil, errors.New("diagram must have exactly two rows")
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[0])%2 != 0 {
		return nil, errors.New("diagram must have an even number of cups")
	}
	for _, row := range rows {
		for i := 0; i < len(row); i++ {
			if _, ok := plantNames[row[i]]; !ok {
				return nil, fmt.Errorf("invalid cup code %q", row[i])
			}
		}
	}
	seen := make(map[string]bool, len(children))
	for _, child := range children {
		if seen[child] {
			return nil, fmt.Errorf("duplicate child name %q", child)
		}
		seen[child] = true
	}
	if 2*len(children) > len(rows[0]) {
		return nil, errors.New("too many children for the number of cups")
	}
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	indices := make(map[string]int, len(sorted))
	for i, child := range sorted {
		indices[child] = i
	}
	return &Garden{
		rows:    [2]string{rows[0], rows[1]},
		indices: indices,
	}, nil
}

// Plants returns the four plants belonging to the named child, in the
// order: first row left, first row right, second row left, second row
// right.  The boolean result is false if the child is not in the garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	pos, ok := g.indices[child]
	if !ok {
		return nil, false
	}
	off := 2 * pos
	return []string{
		plantNames[g.rows[0][off]],
		plantNames[g.rows[0][off+1]],
		plantNames[g.rows[1][off]],
		plantNames[g.rows[1][off+1]],
	}, true
}
